select is((select v->>'entry_method' from data where k='approved'),'staff_reviewed_api_attachment_v2','Approval identifies canonical original contract');
select is((select v#>>'{source_context,capture_contract}' from data where k='approved'),'canonical_api_original_v1','Stable metadata and file identity retain canonical provenance');
select is(to_jsonb(pg_temp.approve_original()),(select v from data where k='approved'),'Exact approval replay preserves saved record');
select throws_ok($$select pg_temp.approve_original('approval',null,true,'Different title')$$,'23505',null,'Approval UUID cannot change reviewed intent');
select throws_ok($$select pg_temp.approve_original('correction')$$,'40001',null,'Correction requires exact predecessor');
insert into data select 'corrected',to_jsonb(pg_temp.approve_original('correction',(select id from fx where k='approval')));
select is((select(v->>'version')::integer from data where k='corrected'),2,'Canonical original correction appends version2');
select is((select v#>>'{source_context,file_id}' from data where k='corrected'),(select v#>>'{request,file_id}' from data where k='ready'),'Separate file ID remains bound to approval');
insert into data select 'chart-page',read_ezyvet_attachment_chart((select id from fx where k='pet'),null,null,1);
select is((select v#>>'{records,0,record,id}' from data where k='chart-page'),(select id::text from fx where k='correction'),'Chart starts at latest reviewed correction');
select is((select v#>>'{records,0,is_latest}' from data where k='chart-page'),'true','Latest review marked separately');
select is((select v#>>'{records,0,source_current}' from data where k='chart-page'),'true','Chart verifies canonical source currentness');
select ok(not (select (v#>'{records,0,record}') ? 'source_context' from data where k='chart-page'),'Chart omits raw source context');
insert into data select 'chart-older',read_ezyvet_attachment_chart((select id from fx where k='pet'),(select(v#>>'{next_cursor,before_at}')::timestamptz from data where k='chart-page'),(select(v#>>'{next_cursor,before_id}')::uuid from data where k='chart-page'),1);
select is((select v#>>'{records,0,is_latest}' from data where k='chart-older'),'false','Earlier reviewed version remains discoverable as superseded');
select is((select v->>'has_more' from data where k='chart-older'),'false','Chart pagination terminates');
