select is((select v#>>'{snapshot,schema_version}' from data where k='api-preview'),'9','Preview identifies schema9');
select is((select v#>>'{snapshot,attachments,0,bucket}' from data where k='api-preview'),'ezyvet-attachment-originals','API original uses canonical private bucket');
