select is(jsonb_array_length((select v#>'{snapshot,imported_prescriptions}' from data where k='api-preview')),0,'API-only preview does not invent prescriptions');
select is((select v->>'source_hash' from data where k='api-preview'),(select encode(sha256(convert_to((v->'snapshot')::text,'UTF8')),'hex') from data where k='api-preview'),'Preview digest binds the entire reviewed snapshot');
insert into fx select 'release-weight',id from record_patient_weight((select id from fx where k='pet'),12.3,'kg',(now() at time zone 'America/Denver')::date);
insert into data select 'mixed-api-preview',pg_temp.api_preview(jsonb_build_object('api_attachment_ids',jsonb_build_array((select id from fx where k='correction')),'weight_ids',jsonb_build_array((select id from fx where k='release-weight'))));
insert into data select 'legacy-weight-preview',release_preview_v8_internal((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','attachment@example.test',jsonb_build_object('weight_ids',jsonb_build_array((select id from fx where k='release-weight'))));
select is(jsonb_array_length((select v#>'{snapshot,weights}' from data where k='mixed-api-preview')),1,'Mixed API preview retains explicitly selected native weight');
select is((select v#>'{snapshot,weights}' from data where k='mixed-api-preview'),(select v#>'{snapshot,weights}' from data where k='legacy-weight-preview'),'Mixed preview preserves schema8 native weight representation');
select is(jsonb_array_length((select v#>'{snapshot,attachments}' from data where k='mixed-api-preview')),1,'Mixed native/API selection includes only the selected original');
select throws_ok($$select pg_temp.api_preview(null,'other@example.test')$$,'42501',null,'API-only preview retains household recipient validation');
select throws_ok($$select pg_temp.api_preview('{"api_attachment_ids":[],"unknown_ids":[]}')$$,'23514',null,'Preview rejects unknown source families');
select throws_ok($$select pg_temp.api_preview('{}')$$,'23514',null,'Empty preview does not select records implicitly');
select throws_ok($$select pg_temp.api_preview(jsonb_build_object('api_attachment_ids',(select jsonb_agg(gen_random_uuid()) from generate_series(1,21))))$$,'23514',null,'Preview caps explicit API selection at20');
select throws_ok($$select pg_temp.api_preview(jsonb_build_object('api_attachment_ids',jsonb_build_array((select id from fx where k='correction')),'imported_prescription_ids',jsonb_build_array(gen_random_uuid())))$$,'23514',null,'Mixed preview still validates canonical prescription selection');
select throws_ok($$select release_api_attachment_document(jsonb_set((select v->0 from data where k='release-original'),'{capture,file_size}','20971521'))$$,'23514',null,'Original mapper rejects oversized file');
select throws_ok($$select release_api_attachment_document(jsonb_set((select v->0 from data where k='release-original'),'{capture,bucket_id}','"patient-documents"'))$$,'23514',null,'API source cannot masquerade as a native document');
select ok(not has_function_privilege('authenticated','release_preview_v9_internal(uuid,uuid,text,text,jsonb)','execute'),'Schema9 composition remains private behind authorized wrappers');
select ok(not has_function_privilege('service_role','release_api_attachment_document(jsonb)','execute'),'Original mapper is not a direct worker entrypoint');
-- Source discovery is current-only; chart history remains complete.
set local role authenticated;
insert into data select 'api-candidates',list_record_release_sources_v9((select id from fx where k='pet'));
select is(jsonb_array_length((select v->'api_attachment_ids' from data where k='api-candidates')),1,'Release chooser offers only latest approved API original');
